/**
 * Identifiants absents du texte source (alertes à enregistrer).
 * @returns {string[]}
 */
function alertesSource(verifications) {
  return verifications.filter((v) => !v.present).map((v) => `${v.champ} « ${v.valeur} » absent du texte source`);
}
